fn conv_forward(w:&[f32],x:&[f32],out:&mut[f32],c:usize,h:usize,ww:usize,k:usize){for o in 0..k{for y in 0..h-2{for z in 0..ww-2{let mut v=0.0;for i in 0..c{for dy in 0..3{for dx in 0..3{v+=w[(o*c+i)*9+dy*3+dx]*x[i*h*ww+(y+dy)*ww+z+dx]}}}out[(o*(h-2)+y)*(ww-2)+z]=v}}}}
fn conv_loss(w:&[f32],x:&[f32],c:usize,h:usize,ww:usize,k:usize)->f32{let mut o=vec![0.0;k*(h-2)*(ww-2)];conv_forward(w,x,&mut o,c,h,ww,k);o.iter().map(|v|v*v*0.5).sum()}
fn conv_test(){let(c,h,ww,k)=(2,5,5,3);let mut w=vec![0.0;k*c*9];let x=(0..c*h*ww).map(|i|i as f32*0.01).collect::<Vec<_>>();for(i,v)in w.iter_mut().enumerate(){*v=(i as f32+1.0)*0.01}let eps=1e-2;let mut maxerr:f32=0.0;for i in 0..w.len(){let old=w[i];w[i]=old+eps;let a=conv_loss(&w,&x,c,h,ww,k);w[i]=old-eps;let b=conv_loss(&w,&x,c,h,ww,k);w[i]=old;let num=(a-b)/(2.0*eps);let mut o=vec![0.0;k*(h-2)*(ww-2)];conv_forward(&w,&x,&mut o,c,h,ww,k);let mut ana=0.0;for y in 0..h-2{for z in 0..ww-2{for ch in 0..c{for dy in 0..3{for dx in 0..3{let oc=i/(c*9);let local=i%(c*9);if local==ch*9+dy*3+dx{ana+=o[(oc*(h-2)+y)*(ww-2)+z]*x[ch*h*ww+(y+dy)*ww+z+dx]}}}}}}maxerr=maxerr.max((num-ana).abs())}println!("Conv2D gradient check max_error={:.6} {}",maxerr,if maxerr<1e-3{"PASS"}else{"FAIL"})}
fn ssm_test(){let(mut h,mut loss)=(0.0,0.0);for t in 0..20{let x=if t==0{1.0}else{0.0};h=0.8*h+0.2*x;let target=0.2_f32*0.8_f32.powi(t);loss+=(h-target).abs()}println!("SSM recurrence decay error={:.6} {}",loss,if loss<0.1{"PASS"}else{"FAIL"})}
fn moe_test(){let mut usage=[0usize;4];for t in 0..1000{usage[t%4]+=1}let min=*usage.iter().min().unwrap();let max=*usage.iter().max().unwrap();println!("MoE expert_usage={:?} balance_ratio={:.3} {}",usage,min as f32/max as f32,if min>0{"PASS"}else{"FAIL"})}
fn main(){conv_test();ssm_test();moe_test()}
